 {
  var root=Path.Combine(State.Home,"媒体 中文 日本語");var work=Path.Combine(root,"社团","星社","系列甲","作品");var cd=Path.Combine(work,"CD1");Directory.CreateDirectory(cd);var audio=Path.Combine(cd,"01 耳语.wav");WriteWave(audio,80);File.WriteAllText(Path.ChangeExtension(audio,"vtt"),"WEBVTT\n\n"+string.Join("\n\n",Enumerable.Range(0,20).Select(i=>$"00:{i*3:00}.000 --> 00:{i*3+2:00}.900\n第{i}句・かな\n多行字幕")));
